      "Firefox permission needed": "مجوز Firefox لازم است",
      "Firefox requires this permission even in normal windows. Open menu ☰ → Extensions and Themes. On Tor Connect, click ⋯ → Manage. Under “Run in Private Windows,” select “Allow,” then return here and try again.": "Firefox حتی در پنجره‌های معمولی به این مجوز نیاز دارد. منوی ☰ → Extensions and Themes را باز کنید. در Tor Connect روی ⋯ → Manage کلیک کنید. زیر “Run in Private Windows,” گزینه “Allow”, را انتخاب کنید، سپس به اینجا بازگردید و دوباره امتحان کنید.",
      "For the live Chrome log, open chrome://extensions, find Tor Connect, then click Service worker. Look for entries beginning [Tor extension].": "For the live Chrome log, open chrome://extensions, find Tor Connect, then click Service worker. Look for entries beginning [Tor extension].",
