      "Firefox permission needed": "Se necesita permiso de Firefox",
      "Firefox requires this permission even in normal windows. Open menu ☰ → Extensions and Themes. On Tor Connect, click ⋯ → Manage. Under “Run in Private Windows,” select “Allow,” then return here and try again.": "Firefox requiere este permiso incluso en ventanas normales. Abre el menú ☰ → Extensions and Themes. En Tor Connect, haz clic en ⋯ → Manage. Bajo “Run in Private Windows,” selecciona “Allow,” luego vuelve aquí e inténtalo de nuevo.",
