      "Firefox needs “Run in Private Windows” on to route your traffic, even in normal windows.": "Firefox को सामान्य विंडोज़ में भी ट्रैफ़िक रूट करने के लिए “Run in Private Windows” चालू होना आवश्यक है।",
      "Firefox permission needed": "Firefox की अनुमति आवश्यक है",
      "Firefox requires this permission even in normal windows. Open menu ☰ → Extensions and Themes. On Tor Connect, click ⋯ → Manage. Under “Run in Private Windows,” select “Allow,” then return here and try again.": "Firefox को सामान्य विंडोज़ में भी यह अनुमति चाहिए। मेनू ☰ → Extensions and Themes खोलें। Tor Connect पर ⋯ → Manage क्लिक करें। “Run in Private Windows”, के अंतर्गत “Allow”, चुनें, फिर यहाँ वापस आएं और पुनः प्रयास करें।",
      "For the live Chrome log, open chrome://extensions, find Tor Connect, then click Service worker. Look for entries beginning [Tor extension].": "For the live Chrome log, open chrome://extensions, find Tor Connect, then click Service worker. Look for entries beginning [Tor extension].",
