      "Firefox needs “Run in Private Windows” on to route your traffic, even in normal windows.": "Firefox требует включённого “Run in Private Windows” для маршрутизации трафика, даже в обычных окнах.",
      "Firefox permission needed": "Требуется разрешение Firefox",
