      "Firefox permission needed": "Firefox অনুমতি প্রয়োজন",
      "Firefox requires this permission even in normal windows. Open menu ☰ → Extensions and Themes. On Tor Connect, click ⋯ → Manage. Under “Run in Private Windows,” select “Allow,” then return here and try again.": "Firefox-এর সাধারণ উইন্ডোতেও এই অনুমতি প্রয়োজন। মেনু ☰ → Extensions and Themes খুলুন। Tor Connect-এ ⋯ → Manage ক্লিক করুন। “Run in Private Windows”, এর অধীনে “Allow”, বেছে নিন, তারপর এখানে ফিরে আবার চেষ্টা করুন।",
