      "If Tor drops or the extension restarts, your browser traffic stays blocked instead of falling back to your real IP. Press Connect to restore access.": "Tor বন্ধ হলে বা এক্সটেনশন পুনরায় চালু হলে ব্রাউজার ট্রাফিক আসল IP-তে ফেরার বদলে ব্লক থাকে। অ্যাক্সেস পুনরুদ্ধার করতে Connect চাপুন।",
      "If Tor drops you lose internet until you press Connect. That is the point, but it can look like a broken connection.": "Tor বন্ধ হলে Connect না চাপা পর্যন্ত ইন্টারনেট থাকবে না। এটাই উদ্দেশ্য, তবে এটি ভাঙা সংযোগের মতো দেখাতে পারে।",
