      "Finland": "ဖင်လန်",
      "Firefox needs “Run in Private Windows” on to route your traffic, even in normal windows.": "Firefox သည် ပုံမှန်ဝင်းဒိုးများတွင်ပါ သင့်ကွန်ရက်လမ်းကြောင်းကို သွားနိုင်ရန် “Run in Private Windows” ဖွင့်ထားရမည်။",
