      "Firefox requires this permission even in normal windows. Open menu ☰ → Extensions and Themes. On Tor Connect, click ⋯ → Manage. Under “Run in Private Windows,” select “Allow,” then return here and try again.": "Firefox သည် ပုံမှန်ဝင်းဒိုးများတွင်ပါ ဤခွင့်ပြုချက် လိုအပ်သည်။ မီနူး ☰ → Extensions and Themes ကိုဖွင့်ပါ။ Tor Connect တွင် ⋯ → Manage ကိုနှိပ်ပါ။ “Run in Private Windows”, အောက်တွင် “Allow”, ကိုရွေးချယ်ပြီး ဤနေရာသို့ ပြန်လာ၍ ထပ်မံကြိုးစားပါ။",
