      "If Tor Connect is useful to you, consider supporting its development.": "Tor Connect သင့်အတွက် အသုံးဝင်လျှင် ၎င်း၏ ဖွံ့ဖြိုးမှုကို ပံ့ပိုးရန် စဉ်းစားပါ။",
      "If Tor drops or the extension restarts, your browser traffic stays blocked instead of falling back to your real IP. Press Connect to restore access.": "Tor ကျသွားလျှင် သို့ extension ပြန်လည်စတင်လျှင် သင်၏ ဘရောက်ဇာ traffic သည် သင်၏ အစစ်အမှန် IP သို့ ပြန်မည့်အစား ပိတ်ဆို့ထားမည်။ ဝင်ရောက်ခွင့် ပြန်ရရန် Connect နှိပ်ပါ။",
